#### Dependency Updates

```python
# dependency-update-manager.py
import subprocess
import json
from typing import List, Dict

class DependencyUpdateManager:
    def __init__(self):
        self.components = [
            'mkdocs-platform',
            'rag-service'
        ]

    def check_outdated_packages(self, component: str) -> List[Dict]:
        """Check for outdated packages in a component"""
        result = subprocess.run(
            ['poetry', 'show', '--outdated', '--format=json'],
            cwd=f'.tooling/components/{component}',
            capture_output=True,
            text=True
        )

        if result.returncode == 0:
            return json.loads(result.stdout)
        return []

    def update_package(self, component: str, package: str, version: str = None):
        """Update a specific package"""
        cmd = ['poetry', 'update', package]
        if version:
            cmd = ['poetry', 'add', f'{package}@{version}']

        result = subprocess.run(
            cmd,
            cwd=f'.tooling/components/{component}',
            capture_output=True,
            text=True
        )

        return result.returncode == 0

    def run_tests_after_update(self, component: str) -> bool:
        """Run tests after updating dependencies"""
        result = subprocess.run(
            ['python', '_helpers/verify.py'],
            cwd=f'.tooling/components/{component}',
            capture_output=True,
            text=True
        )

        return result.returncode == 0

    def generate_update_report(self) -> Dict:
        """Generate comprehensive update report"""
        report = {
            'update_date': datetime.now().isoformat(),
            'components': {}
        }

        for component in self.components:
            outdated = self.check_outdated_packages(component)
            report['components'][component] = {
                'outdated_packages': len(outdated),
                'security_updates': [
                    pkg for pkg in outdated
                    if 'security' in pkg.get('description', '').lower()
                ],
                'major_updates': [
                    pkg for pkg in outdated
                    if self.is_major_update(pkg)
                ]
            }

        return report
